{
  "name": "原始广播 UDP 远程过程调用客户端",
  "name_en": "Raw Broadcast UDP RPC Client",
  "manufacturer": "",
  "description": "这是一个非物理的软件通信组件，通过 UDP 广播向指定端口发送基于 XDR 的远程过程调用请求，并处理认证、消息打包解包、超时和回复回调。它适合用于实验系统中的网络服务发现、端口映射查询以及分布式控制服务通信，不直接对应具体实验仪器。",
  "description_en": "This is a non-physical software communication component that sends XDR-based remote procedure calls over UDP broadcast to a specific port and handles authentication, message packing/unpacking, timeouts, and reply callbacks. It is suitable for network service discovery, port-mapper queries, and communication with distributed control services in lab systems, and does not directly correspond to a specific physical instrument.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "建立或初始化广播 UDP 通信连接。",
      "description_en": "Establish or initialize the broadcast UDP communication connection."
    },
    {
      "action_name": "auto-make_call",
      "description": "发送一次远程过程调用并接收回复。",
      "description_en": "Send a remote procedure call and receive replies."
    },
    {
      "action_name": "auto-set_reply_handler",
      "description": "设置用于处理广播回复的回调函数。",
      "description_en": "Set the callback used to handle broadcast replies."
    },
    {
      "action_name": "auto-set_timeout",
      "description": "设置网络调用的超时时间。",
      "description_en": "Set the timeout for network calls."
    },
    {
      "action_name": "auto-pack_auth",
      "description": "打包远程过程调用认证信息。",
      "description_en": "Pack RPC authentication data."
    },
    {
      "action_name": "auto-pack_auth_unix",
      "description": "打包 UNIX 风格的认证信息。",
      "description_en": "Pack UNIX-style authentication data."
    },
    {
      "action_name": "auto-pack_callheader",
      "description": "打包远程过程调用请求头。",
      "description_en": "Pack the RPC call header."
    },
    {
      "action_name": "auto-pack_replyheader",
      "description": "打包远程过程调用回复头。",
      "description_en": "Pack the RPC reply header."
    },
    {
      "action_name": "auto-unpack_auth",
      "description": "解包远程过程调用认证信息。",
      "description_en": "Unpack RPC authentication data."
    },
    {
      "action_name": "auto-unpack_callheader",
      "description": "解包远程过程调用请求头。",
      "description_en": "Unpack the RPC call header."
    },
    {
      "action_name": "auto-unpack_replyheader",
      "description": "解包远程过程调用回复头。",
      "description_en": "Unpack the RPC reply header."
    },
    {
      "action_name": "auto-start_call",
      "description": "开始构建一次远程过程调用消息。",
      "description_en": "Begin constructing an RPC call message."
    },
    {
      "action_name": "auto-do_call",
      "description": "执行底层远程过程调用事务。",
      "description_en": "Execute the low-level RPC transaction."
    },
    {
      "action_name": "auto-mkcred",
      "description": "创建远程过程调用凭据。",
      "description_en": "Create RPC credentials."
    },
    {
      "action_name": "auto-mkverf",
      "description": "创建远程过程调用校验信息。",
      "description_en": "Create an RPC verifier."
    },
    {
      "action_name": "auto-call_0",
      "description": "调用空过程以测试服务可达性。",
      "description_en": "Invoke the null procedure to test service reachability."
    },
    {
      "action_name": "auto-pack_mapping",
      "description": "打包端口映射条目。",
      "description_en": "Pack a port-mapper mapping entry."
    },
    {
      "action_name": "auto-pack_pmaplist",
      "description": "打包端口映射列表。",
      "description_en": "Pack a port-mapper mapping list."
    },
    {
      "action_name": "auto-pack_call_args",
      "description": "打包远程调用参数。",
      "description_en": "Pack remote call arguments."
    },
    {
      "action_name": "auto-unpack_mapping",
      "description": "解包端口映射条目。",
      "description_en": "Unpack a port-mapper mapping entry."
    },
    {
      "action_name": "auto-unpack_pmaplist",
      "description": "解包端口映射列表。",
      "description_en": "Unpack a port-mapper mapping list."
    },
    {
      "action_name": "auto-unpack_call_result",
      "description": "解包远程调用结果。",
      "description_en": "Unpack the remote call result."
    },
    {
      "action_name": "auto-set",
      "description": "在端口映射服务中注册一个映射。",
      "description_en": "Register a mapping in the port-mapper service."
    },
    {
      "action_name": "auto-unset",
      "description": "从端口映射服务中移除一个映射。",
      "description_en": "Remove a mapping from the port-mapper service."
    },
    {
      "action_name": "auto-get_port",
      "description": "查询服务对应的端口号。",
      "description_en": "Query the port number for a service."
    },
    {
      "action_name": "auto-dump",
      "description": "列出端口映射服务中的注册项。",
      "description_en": "List registrations in the port-mapper service."
    },
    {
      "action_name": "auto-callit",
      "description": "通过端口映射服务请求间接远程调用。",
      "description_en": "Request an indirect remote call through the port-mapper service."
    },
    {
      "action_name": "auto-my_reply_handler",
      "description": "处理广播端口映射调用的回复。",
      "description_en": "Handle replies from broadcast port-mapper calls."
    },
    {
      "action_name": "auto-register",
      "description": "注册一个可处理请求的服务。",
      "description_en": "Register a service that can handle requests."
    },
    {
      "action_name": "auto-unregister",
      "description": "注销一个已注册的服务。",
      "description_en": "Unregister a previously registered service."
    },
    {
      "action_name": "auto-handle",
      "description": "处理一次收到的远程过程调用请求。",
      "description_en": "Handle an incoming RPC request."
    },
    {
      "action_name": "auto-turn_around",
      "description": "将请求转换为对应的回复消息。",
      "description_en": "Turn a request into the corresponding reply message."
    },
    {
      "action_name": "auto-handle_0",
      "description": "处理空过程请求。",
      "description_en": "Handle a null procedure request."
    },
    {
      "action_name": "auto-addpackers",
      "description": "添加消息打包与解包器。",
      "description_en": "Add message packers and unpackers."
    },
    {
      "action_name": "auto-loop",
      "description": "运行服务处理循环。",
      "description_en": "Run the service processing loop."
    },
    {
      "action_name": "auto-session",
      "description": "处理一次服务会话。",
      "description_en": "Process a service session."
    },
    {
      "action_name": "auto-forkingloop",
      "description": "以分叉方式运行服务循环。",
      "description_en": "Run the service loop using process forking."
    },
    {
      "action_name": "auto-forksession",
      "description": "在子进程中处理一次服务会话。",
      "description_en": "Handle a service session in a child process."
    }
  ],
  "tag_hints": [
    "UDP broadcast RPC",
    "ONC RPC/XDR",
    "port mapper",
    "network service discovery",
    "distributed lab control",
    "reply handling",
    "timeout management"
  ]
}

